use std::time::{SystemTime, UNIX_EPOCH};
use std::env;

/// Generates a trace header for any generated file
pub fn generate_trace_header(
    operation: &str,
    input_file: Option<&str>,
    processor_function: &str,
    source_location: &str,
) -> String {
    let timestamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs();
    
    let pid = std::process::id();
    let cwd = env::current_dir()
        .map(|p| p.display().to_string())
        .unwrap_or_else(|_| "unknown".to_string());
    
    format!(
        "// TRACE: Generated by split-decls-rs\n\
         // OPERATION: {}\n\
         // INPUT: {}\n\
         // PROCESSOR: {}\n\
         // SOURCE_LOC: {}\n\
         // TIMESTAMP: {}\n\
         // PID: {}\n\
         // CWD: {}\n\
         // ========================================\n",
        operation,
        input_file.unwrap_or("none"),
        processor_function,
        source_location,
        timestamp,
        pid,
        cwd
    )
}

/// Macro to generate trace header with current location
#[macro_export]
macro_rules! trace_header {
    ($operation:expr, $input:expr, $processor:expr) => {
        $crate::trace_header::generate_trace_header(
            $operation,
            $input,
            $processor,
            &format!("{}:{}", file!(), line!())
        )
    };
}
